/**
 * Every failure crosses the FFI as one message the screen can show verbatim.
 */
sealed class WalletException: kotlin.Exception() {
    
    class Message(
        
        val `msg`: kotlin.String
        ) : WalletException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WalletException> {
        override fun lift(error_buf: RustBuffer.ByValue): WalletException = FfiConverterTypeWalletError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeWalletError : FfiConverterRustBuffer<WalletException> {
    override fun read(buf: ByteBuffer): WalletException {
        

        return when(buf.getInt()) {
            1 -> WalletException.Message(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WalletException): ULong {
        return when(value) {
            is WalletException.Message -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: WalletException, buf: ByteBuffer) {
        when(value) {
            is WalletException.Message -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Progress lines for the ACTIVITY panel. `level`: "info" | "ok" | "error".
 */
public interface Progress {
    
    fun `onLog`(`level`: kotlin.String, `line`: kotlin.String, `link`: kotlin.String?)
    
    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceProgress {
    internal object `onLog`: UniffiCallbackInterfaceProgressMethod0 {
        override fun callback(`uniffiHandle`: Long,`level`: RustBuffer.ByValue,`line`: RustBuffer.ByValue,`link`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeProgress.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onLog`(
                    FfiConverterString.lift(`level`),
                    FfiConverterString.lift(`line`),
                    FfiConverterOptionalString.lift(`link`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
