/**
 * @suppress
 */
public object FfiConverterSequenceTypeNoteView: FfiConverterRustBuffer<List<NoteView>> {
    override fun read(buf: ByteBuffer): List<NoteView> {
        val len = buf.getInt()
        return List<NoteView>(len) {
            FfiConverterTypeNoteView.read(buf)
        }
    }

    override fun allocationSize(value: List<NoteView>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeNoteView.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<NoteView>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeNoteView.write(it, buf)
        }
    }
